/** Native work is optional evidence; only canonical physical return can credit a consenting service job. */
public final class ServiceWorkService {
 public static final String KEY="kingdom_smp_service_output";
 public record Quote(UUID nonce,long revision,String action,UUID reference,UUID provider,ItemStack held,List<ItemStack> before,List<ItemStack> after,UUID wearStore,UUID wear,String quest,long issued,String text) {
  public Quote{held=held.copy();before=before.stream().map(ItemStack::copy).toList();after=after.stream().map(ItemStack::copy).toList();}
  @Override public ItemStack held(){return held.copy();}
  @Override public List<ItemStack> before(){return before.stream().map(ItemStack::copy).toList();}
  @Override public List<ItemStack> after(){return after.stream().map(ItemStack::copy).toList();}
 }
 private record Candidate(UUID id,UUID consent,ServerPlayer player,AnvilMenu menu,BlockPos site,ItemStack output,ItemStack donor,int materials,int stock,int levels,int cost) { }
 private static final Map<ServerPlayer,Quote> QUOTES=new WeakHashMap<>();private static final Map<AnvilMenu,Candidate> CANDIDATES=new WeakHashMap<>();
 private ServiceWorkService() { }
 public static void closed(net.neoforged.neoforge.event.entity.player.PlayerContainerEvent.Close event){if(event.getEntity() instanceof ServerPlayer&&event.getContainer() instanceof AnvilMenu menu){CANDIDATES.remove(menu);EnchantedToolService.abandon(menu);}}
 public static void close(ServerPlayer p){QUOTES.remove(p);}
 public static boolean eligible(ServerPlayer p){return eligible(p,ServiceWorkState.SMITH);}
 public static boolean eligible(ServerPlayer p,String quest){if(!ServiceWorkState.supported(quest)||p==null||!TreeQuestService.real(p))return false;var store=CommerceService.initializedStore(p.server).orElse(null);if(store==null||store.quarantined())return false;var roster=store.professions(p.getUUID());var role=ServiceWorkState.role(quest);var definition=ApprovedProfessionContent.get(quest);return roster.isActive(role)&&roster.progressBand(role)==definition.rank()&&ServiceWorkQuests.catalog().mayAttempt(role,quest,roster.track(role).completedQuestIds())&&com.mohymods.kingdomsmp.contribution.ContributionService.kingdom(p.server).attainedTier()>=definition.minimumTier();}
 private static String counter(ServerPlayer p){CommerceService.requireResidentCounter(p);var project=CommerceService.counterProject(p);if(project==null||!ConstructionService.structureIntact(p.serverLevel(),project))throw new IllegalStateException("Visit the intact profession resident for consenting equipment services");if(project.blueprint().toString().equals(Profession.BLACKSMITH.buildingId()))return ServiceWorkState.SMITH;if(project.blueprint().toString().equals(Profession.LIBRARIAN.buildingId()))return ServiceWorkState.LIBRARY;throw new IllegalStateException("Equipment services require a Blacksmith or Library counter");}
 private static void inventory(ServerPlayer p)throws IOException{if(!TreeQuestService.real(p)||p.containerMenu!=p.inventoryMenu||!p.containerMenu.getCarried().isEmpty())throw new IllegalStateException("Close containers and hold your equipment in the main hand");var s=CommerceService.store(p.server);if(s.quarantined()||s.pendingSale().isPresent()||s.pendingTransfer().isPresent()||s.pendingItem().isPresent())throw new IllegalStateException("Resolve pending native inventory recovery first");CommerceService.verifyReceipt(p,s);}
 private static CompoundTag encoded(ServerPlayer p,ItemStack item){return (CompoundTag)item.save(p.registryAccess());}
 private static UUID outputId(ServerPlayer p,ItemStack stack){var tag=stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getCompound(KEY);return tag.hasUUID("store")&&tag.hasUUID("id")&&tag.getUUID("store").equals(CommerceService.store(p.server).id())?tag.getUUID("id"):null;}
 public static Quote review(ServerPlayer p,String selected)throws IOException {
  String quest=counter(p);inventory(p);var store=CommerceService.store(p.server);var role=ServiceWorkState.role(quest);var held=p.getMainHandItem().copy();var before=new ArrayList<ItemStack>();for(int i=0;i<36;i++)before.add(p.getInventory().getItem(i).copy());var after=before.stream().map(ItemStack::copy).toList();String action,text;UUID reference,provider=null,wearStore=null,wear=null;
  if(selected.startsWith("service_offer:")){
   action="offer";provider=UUID.fromString(selected.substring(14));var smith=p.server.getPlayerList().getPlayer(provider);if(smith==null||smith==p||smith.serverLevel()!=p.serverLevel()||p.distanceToSqr(smith)>256||!eligible(smith,quest)||!ProfessionService.available(smith,role))throw new IllegalStateException("The selected eligible profession provider must attend within16blocks");if(!counter(smith).equals(quest))throw new IllegalStateException("Provider must attend this same service counter");
   if(held.getCount()!=1||held.getDamageValue()<1||!RepairEvidence.eligible(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(held.getItem()).toString()))throw new IllegalStateException("Hold one genuinely worn iron item in your current main-hand inventory");
   var data=RepairSavedData.get(p.server).evidence();var marker=held.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getCompound(RepairService.KEY);if(!marker.hasUUID("store")||!marker.hasUUID("id")||!marker.getUUID("store").equals(data.identity()))throw new IllegalStateException("Use a tracked genuinely worn item; unknown historical wear is not inferred");var proof=data.get(marker.getUUID("id"));if(proof==null||proof.credited()!=null||proof.damage()!=held.getDamageValue()||!proof.item().equals(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(held.getItem()).toString()))throw new IllegalStateException("Unknown, already credited or changed wear source");if(quest.equals(ServiceWorkState.LIBRARY)&&held.getOrDefault(DataComponents.ENCHANTMENTS,net.minecraft.world.item.enchantment.ItemEnchantments.EMPTY).isEmpty())throw new IllegalStateException("Library restoration requires genuinely worn enchanted iron equipment; incompatible or stripped enchantments never count");wearStore=data.identity();wear=proof.id();reference=UUID.randomUUID();text="Authorize "+smith.getGameProfile().getName()+" to "+(quest.equals(ServiceWorkState.SMITH)?"repair":"compatibly improve enchantments on")+" this exact item currently held by you. No items or money move now. Hand it over through normal Minecraft transfer. The provider must pay actual native materials and XP, then return the exact output into your recoverable private item mail. You may revoke before return. Each tracked item can earn service credit only once.";
  }else if(selected.startsWith("service_revoke:")){
   action="revoke";reference=UUID.fromString(selected.substring(15));var consent=store.serviceWork().consent(reference).orElseThrow();if(!consent.quest().equals(quest)||!consent.owner().equals(p.getUUID())||!consent.active()||consent.returned())throw new IllegalStateException("No active consent owned by you");text="Withdraw this equipment service consent. No items are destroyed or moved. Already handed-over equipment must be returned normally; no service credit can be claimed after revocation.";
  }else if(selected.startsWith("service_return:")){
   action="return";reference=UUID.fromString(selected.substring(15));if(!eligible(p,quest)||!ProfessionService.available(p,role))throw new IllegalStateException("Active eligible smith and maintained premises required");var state=store.serviceWork();var output=state.output(reference).orElseThrow();var consent=state.consent(output.consent()).orElseThrow();if(!consent.quest().equals(quest)||!consent.provider().equals(p.getUUID())||!consent.active()||consent.returned()||output.spent())throw new IllegalStateException("Customer consent was revoked or this source was already returned");int slot=-1;for(int i=0;i<36;i++)if(reference.equals(outputId(p,before.get(i)))&&output.item().equals(encoded(p,before.get(i)))){slot=i;break;}if(slot<0)throw new IllegalStateException("Bring the exact authenticated native repaired output; copies of tags alone do not authorize it");after=new ArrayList<>(after);after.set(slot,ItemStack.EMPTY);text="Permanently transfer this actual repaired item to its consenting customer's private recoverable item mail. The exact item leaves your inventory. Return, source use and one job record commit together. No coins or equipment are created. Three jobs across two different customers complete the approved service quest.";
  }else throw new IllegalArgumentException("Unknown equipment service action");
  var q=new Quote(UUID.randomUUID(),store.revision(),action,reference,provider,held,List.copyOf(before),List.copyOf(after),wearStore,wear,quest,System.nanoTime(),text);QUOTES.put(p,q);return q;
 }
 public static String confirm(ServerPlayer p,UUID nonce)throws IOException{
  String quest=counter(p);inventory(p);var q=QUOTES.remove(p);var store=CommerceService.store(p.server);if(q==null||!q.quest().equals(quest)||!q.nonce().equals(nonce)||q.revision()!=store.revision()||System.nanoTime()-q.issued()>30_000_000_000L)throw new IllegalStateException("Service review expired or authoritative records changed");for(int i=0;i<36;i++)if(!ItemStack.matches(p.getInventory().getItem(i),q.before().get(i)))throw new IllegalStateException("Inventory changed; review again");
  if(q.action().equals("offer")){var fresh=review(p,"service_offer:"+q.provider());QUOTES.remove(p);if(!ItemStack.matches(fresh.held(),q.held())||!Objects.equals(fresh.wear(),q.wear())||!Objects.equals(fresh.wearStore(),q.wearStore()))throw new IllegalStateException("Current ownership/wear changed");store.authorizeService(q.reference(),p.getUUID(),q.provider(),q.quest(),q.wearStore(),q.wear(),encoded(p,q.held()));return "Current inventory owner consent saved. Transfer the item normally to your chosen smith.";}
  if(q.action().equals("revoke")){store.revokeService(q.nonce(),p.getUUID(),q.reference());return "Consent withdrawn; no items or money moved.";}
  if(!eligible(p,q.quest()))throw new IllegalStateException("Service prerequisites changed");var out=store.serviceWork().output(q.reference()).orElseThrow();var old=p.getPersistentData().copy();boolean checkpointStarted=false;
  try{CommerceService.checkpoint(p);var pending=store.prepareServiceReturn(q.nonce(),p.getUUID(),q.reference(),out.item());for(int i=0;i<36;i++)p.getInventory().setItem(i,q.after().get(i).copy());CommerceService.putReceipt(p,new EconomyStore.Receipt(store.id(),pending.sequence()));checkpointStarted=true;CommerceService.checkpoint(p);if(!store.recoverItem(CommerceService.receipt(AtomicNbt.read(CommerceService.playerFile(p.server,p.getUUID())))))throw new IOException("Native service return receipt did not commit");p.getInventory().setChanged();p.inventoryMenu.sendAllDataToRemote();return "Exact repaired item returned into customer mail; canonical source spent and one service job saved.";}
  catch(IOException|RuntimeException e){if(!checkpointStarted){for(int i=0;i<36;i++)p.getInventory().setItem(i,q.before().get(i).copy());for(var key:new HashSet<>(p.getPersistentData().getAllKeys()))p.getPersistentData().remove(key);p.getPersistentData().merge(old);}if(!checkpointStarted&&store.pendingItem().isEmpty()&&!store.quarantined()&&(e instanceof IllegalArgumentException||e instanceof IllegalStateException))throw e;store.quarantine();p.connection.disconnect(net.minecraft.network.chat.Component.literal("Equipment return interrupted; restore matching native inventory and canonical checkpoints"));throw e;}
 }
 private static boolean repairShape(ItemStack left,ItemStack result){var a=left.copy();var b=result.copy();for(var type:List.of(DataComponents.DAMAGE,DataComponents.REPAIR_COST)){a.remove(type);b.remove(type);}return ItemStack.isSameItemSameComponents(a,b);}
 public static void preview(Player player,AnvilMenu menu){CANDIDATES.remove(menu);if(!(player instanceof ServerPlayer p))return;try{
  if(menu.getSlot(0).getItem().isEmpty())return;var consent=CommerceService.store(p.server).serviceWork().forInput(p.getUUID(),encoded(p,menu.getSlot(0).getItem())).orElse(null);if(consent==null)return;boolean library=consent.quest().equals(ServiceWorkState.LIBRARY);if(!eligible(p,consent.quest())||!ProfessionService.available(p,ServiceWorkState.role(consent.quest()))||p.containerMenu!=menu||menu.getCost()<1||menu.getCost()>=40||menu.getCost()>p.experienceLevel)return;var left=menu.getSlot(0).getItem();var right=menu.getSlot(1).getItem();var result=menu.getSlot(2).getItem();if(left.getCount()!=1||result.getCount()!=1||result.getItem()!=left.getItem())return;if(library){if(right.getCount()!=1||!right.is(Items.ENCHANTED_BOOK)||!right.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().isEmpty()||!EnchantedToolService.compatible(left,right,result))return;}else if(!repairShape(left,result)||!right.is(Items.IRON_INGOT)||!ItemStack.isSameItemSameComponents(right,new ItemStack(Items.IRON_INGOT))||result.getDamageValue()>=left.getDamageValue()||!Objects.equals(result.get(DataComponents.ENCHANTMENTS),left.get(DataComponents.ENCHANTMENTS)))return;
  var wear=RepairSavedData.get(p.server).evidence();var record=wear.get(consent.wear());if(!wear.identity().equals(consent.wearStore())||record==null||record.credited()!=null||record.damage()!=left.getDamageValue())return;
  record Site(net.minecraft.world.level.Level level,BlockPos pos){}var site=((NativeCombinerAccess)menu).kingdom$access().evaluate((level,pos)->new Site(level,pos.immutable())).orElse(null);if(site==null||site.level()!=p.serverLevel()||!p.serverLevel().hasChunkAt(site.pos())||!p.serverLevel().getBlockState(site.pos()).is(BlockTags.ANVIL)||p.distanceToSqr(site.pos().getCenter())>64||PlacementProtection.check(p.serverLevel(),p,site.pos(),site.pos())!=null)return;
  UUID id=UUID.randomUUID();var all=result.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();var tag=new CompoundTag();tag.putUUID("store",CommerceService.store(p.server).id());tag.putUUID("id",id);all.put(KEY,tag);result.set(DataComponents.CUSTOM_DATA,CustomData.of(all));CANDIDATES.put(menu,new Candidate(id,consent.id(),p,menu,site.pos(),result.copy(),right.copy(),0,right.getCount(),p.experienceLevel,menu.getCost()));
 }catch(RuntimeException e){TreeLifecycle.failure(p.server,e);}}
 public static Object capture(Player player,AnvilMenu menu,ItemStack output,int materials){var c=CANDIDATES.remove(menu);if(!(player instanceof ServerPlayer p)||c==null||c.player()!=p)return null;try{var nativeStack=(NativeItemIdentityAccessor)(Object)output;var consent=CommerceService.store(p.server).serviceWork().consent(c.consent()).orElse(null);if(consent==null||!consent.active()||!consent.input().equals(encoded(p,menu.getSlot(0).getItem()))||!ItemStack.matches(menu.getSlot(1).getItem(),c.donor())||!(consent.quest().equals(ServiceWorkState.SMITH)?menu.getSlot(1).getItem().is(Items.IRON_INGOT):menu.getSlot(1).getItem().is(Items.ENCHANTED_BOOK))||menu.getSlot(1).getItem().getCount()!=c.stock()||(consent.quest().equals(ServiceWorkState.SMITH)?materials<1||materials>c.stock():materials!=0)||!eligible(p,consent.quest())||p.containerMenu!=menu||p.experienceLevel!=c.levels()||menu.getCost()!=c.cost()||nativeStack.kingdom$nativeItem()!=c.output().getItem()||!nativeStack.kingdom$nativeComponents().equals(((NativeItemIdentityAccessor)(Object)c.output()).kingdom$nativeComponents()))return null;return new Candidate(c.id(),c.consent(),p,menu,c.site(),c.output(),c.donor(),materials,c.stock(),c.levels(),c.cost());}catch(RuntimeException e){TreeLifecycle.failure(p.server,e);return null;}}
 public static void commit(Object proof){if(!(proof instanceof Candidate c))return;var p=c.player();try{var consent=CommerceService.store(p.server).serviceWork().consent(c.consent()).orElseThrow();boolean library=consent.quest().equals(ServiceWorkState.LIBRARY);if(!eligible(p,consent.quest())||!EnchantedToolService.premisesAfterTake(p,ServiceWorkState.role(consent.quest()),c.site())||p.containerMenu!=c.menu()||!c.menu().getSlot(0).getItem().isEmpty()||c.menu().getSlot(1).getItem().getCount()!=c.stock()-(library?1:c.materials())||p.experienceLevel!=c.levels()-c.cost()||PlacementProtection.check(p.serverLevel(),p,c.site(),c.site())!=null)return;CommerceService.store(p.server).issueServiceOutput(c.id(),p.getUUID(),c.consent(),encoded(p,c.output()),library?1:c.materials(),c.cost());}catch(IOException|RuntimeException e){TreeLifecycle.failure(p.server,new IllegalStateException("Native service proof unavailable; native transfer retained",e));}}
 public static String status(ServerPlayer p){return status(p,ServiceWorkState.SMITH);}
 public static String status(ServerPlayer p,String quest){var state=CommerceService.store(p.server).serviceWork();return state.jobs(p.getUUID(),quest)+"/3 returned jobs; "+state.customers(p.getUUID(),quest)+"/2 consenting current owners. Use tracked worn iron gear, native XP/materials and exact customer-mail return. Library work must improve compatible enchantments. Each source counts once.";}
 public static boolean ready(ServerPlayer p){return ready(p,ServiceWorkState.SMITH);}
 public static boolean ready(ServerPlayer p,String quest){var role=ServiceWorkState.role(quest);if(!eligible(p,quest)||CommerceService.store(p.server).professions(p.getUUID()).track(role).completedQuestIds().contains(quest)||!ProfessionService.available(p,role))return false;var s=CommerceService.store(p.server).serviceWork();return s.jobs(p.getUUID(),quest)>=3&&s.customers(p.getUUID(),quest)>=2;}
 public static void complete(ServerPlayer p,UUID operation)throws IOException{complete(p,operation,ServiceWorkState.SMITH);}
 public static void complete(ServerPlayer p,UUID operation,String quest)throws IOException{if(!counter(p).equals(quest)||!ready(p,quest))throw new IllegalStateException(status(p,quest));CommerceService.store(p.server).completeServiceQuest(operation,p.getUUID(),quest);}
 public static com.mojang.brigadier.builder.LiteralArgumentBuilder<net.minecraft.commands.CommandSourceStack> adminCommands(){return net.minecraft.commands.Commands.literal("services").requires(s->s.hasPermission(2)).then(net.minecraft.commands.Commands.argument("player",net.minecraft.commands.arguments.EntityArgument.player()).executes(c->{var p=net.minecraft.commands.arguments.EntityArgument.getPlayer(c,"player");var state=CommerceService.store(p.server).serviceWork();c.getSource().sendSuccess(()->net.minecraft.network.chat.Component.literal("Native customer services: "+p.getGameProfile().getName()+" | returned jobs "+state.jobs(p.getUUID(),ServiceWorkState.SMITH)+" | distinct current owners "+state.customers(p.getUUID(),ServiceWorkState.SMITH)+". Read-only; no repairs, grants or permission changes."),false);for(var consent:state.history(p.getUUID(),16))c.getSource().sendSuccess(()->net.minecraft.network.chat.Component.literal("Service "+consent.id()+" | owner "+consent.owner()+" | provider "+consent.provider()+" | purpose "+consent.quest()+" | native source "+consent.wearStore()+"/"+consent.wear()+" | active "+consent.active()+" | returned "+consent.returned()),false);return 1;}));}
 public static List<CommerceView.Entry> entries(ServerPlayer p){var rows=new ArrayList<CommerceView.Entry>();try{String quest=counter(p);var state=CommerceService.store(p.server).serviceWork();p.server.getPlayerList().getPlayers().stream().filter(v->v!=p&&v.serverLevel()==p.serverLevel()&&p.distanceToSqr(v)<=256&&eligible(v,quest)).sorted(Comparator.comparingDouble(p::distanceToSqr)).limit(3).forEach(v->rows.add(new CommerceView.Entry("service_offer:"+v.getUUID(),"Equipment consent · "+v.getGameProfile().getName(),"Hold your tracked worn iron item. Review permission for this provider; ownership is your current server inventory, never an original-wearer label.",0,"PROF_SERVICE")));state.owned(p.getUUID()).stream().filter(c->c.quest().equals(quest)).limit(3).forEach(c->rows.add(new CommerceView.Entry("service_revoke:"+c.id(),"Withdraw equipment consent","Cancel this owner's repair authorization; items remain where they physically are.",0,"PROF_SERVICE")));if(eligible(p,quest))for(int i=0;i<36&&rows.stream().filter(r->r.id().startsWith("service_return:")).count()<3;i++){var stack=p.getInventory().getItem(i);var id=outputId(p,stack);if(id==null)continue;var out=state.output(id).orElse(null);if(out!=null&&state.consent(out.consent()).orElseThrow().quest().equals(quest)&&!out.spent()&&out.item().equals(encoded(p,stack))&&rows.stream().noneMatch(r->r.id().equals("service_return:"+id)))rows.add(new CommerceView.Entry("service_return:"+id,"Return serviced equipment","Permanently transfer exact native repaired equipment into its consenting customer's recoverable mail. Return and one job record commit together.",0,"PROF_SERVICE"));}}catch(IllegalStateException unavailable){}return List.copyOf(rows);}
}
